def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    markers = {value for value in counts if value != background}
    out = [row[:] for row in grid]

    for marker in markers:
        for r in range(h):
            positions = [c for c, value in enumerate(grid[r]) if value == marker]
            for a, b in zip(positions, positions[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 3
        for c in range(w):
            positions = [r for r in range(h) if grid[r][c] == marker]
            for a, b in zip(positions, positions[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 3
    return out
